import test from 'node:test';
import assert from 'node:assert/strict';
import { buildMissionGraph } from '../../../upstream/lib/intelligence.ts';
import { adaptWorkState } from '../src/model.ts';
import { fixture, sources, MID, AT } from './fixture.ts';
test('adapter reuses real graph IDs and relationships without mutating V4 input', () => { const w = fixture(); const before = JSON.stringify(w); const raw = buildMissionGraph(w, sources); const graph = adaptWorkState(w, sources); assert.deepEqual(graph.nodes.map(n => n.id).sort(), raw.nodes.map(n => n.id).sort()); assert.deepEqual(graph.edges.map(e => e.id).sort(), raw.edges.map(e => e.id).sort()); assert.equal(JSON.stringify(w), before); assert.equal(graph.nodes.find(n => n.id === 'mission:' + MID)?.attributes.evidence, 'Actual evidence content'); assert.equal(graph.nodes.find(n => n.id === 'mission:' + MID)?.provenance.observedAt, AT); });
test('unknown state and source date stay explicitly unknown', () => { const graph = adaptWorkState(null, null); assert.equal(graph.availability, 'unknown'); assert.deepEqual(graph.nodes, []); assert.equal(graph.updatedAt, null); const source = adaptWorkState(fixture(), sources).nodes.find(n => n.id === 'source:report')!; assert.equal(source.provenance.observedAt, null); assert.equal(source.provenance.kind, 'external-snapshot'); assert.equal(source.attributes.file, 'report.md'); });
test('events are retained records, bounded and never used to reconstruct current state', () => { const w = fixture(); const graph = adaptWorkState(w, sources); assert.equal(graph.activity.completeness, 'unknown'); assert.equal(graph.activity.reconstructable, false); assert.equal(graph.activity.events.length, 1); assert.equal(graph.activity.events[0].sequence, 51); assert.equal(graph.activity.events[0].nodeId, 'mission:' + MID); assert.equal(graph.nodes.find(n => n.id === 'mission:' + MID)?.status, 'Working'); });
test('omitted archived and unresolved references are disclosed instead of fabricated nodes', () => { const w = fixture(); w.tasks[0].archived = true; w.command.missions[0].sourceIds.push('unavailable-source'); const g = adaptWorkState(w, null); assert.equal(g.omittedArchived, 1); assert.ok(g.unresolved.some(r => r.to === 'task:' + w.tasks[0].id)); assert.ok(g.unresolved.some(r => r.to === 'source:unavailable-source')); assert.equal(g.sourcesAvailability, 'unknown'); assert.ok(!g.nodes.some(n => n.id === 'source:unavailable-source')); });
test('invalid state, duplicate source IDs and invalid source dates are rejected', () => { const w = fixture(); assert.throws(() => adaptWorkState({ ...w, updatedAt: 'bad' }, sources)); assert.throws(() => adaptWorkState(w, [...sources, ...sources])); assert.throws(() => adaptWorkState(w, [{ ...sources[0], observedAt: 'bad' }])); });
test('source detail never claims a dated snapshot when its timestamp is unknown',()=>{const a=adaptWorkState(fixture(),sources).nodes.find(n=>n.kind==='source')!;assert.match(a.detail,/Quellenstand unbekannt/);assert.doesNotMatch(a.detail,/Datierter Quellenstand/);const b=adaptWorkState(fixture(),[{...sources[0],observedAt:AT}]).nodes.find(n=>n.kind==='source')!;assert.match(b.detail,new RegExp(AT.replaceAll('.','\\.'))) });
